example.code:
// Select 3 Employees
EmployeesCollection coll = new EmployeesCollection();
coll.Query.es.Top = 3;
if (coll.Query.Load())
{
   // Create Our Proxy Stubb
   BusinessObjects.EmployeesCollectionProxyStub server = new BusinessObjects.EmployeesCollectionProxyStub(coll);

   // Serialize it into a string and return this string to Silverlight
   string xml = esDataContractSerializer.ToXml(server);

   // Deserialize the string above into our Client side proxy
   Proxies.EmployeesCollectionProxyStub client = esDataContractSerializer.FromXml(xml, typeof(Proxies.EmployeesCollectionProxyStub))
       as Proxies.EmployeesCollectionProxyStub;

   // Set a property and notice that esRowState goes to Modified
   client.Collection[0].LastName = "crazy_horse";

   // Serialize our client side proxy into xml and send it to the server
   xml = esDataContractSerializer.ToXml(client);

   // Deserialize it on the server, the esRowState is modifed as we would expect
   BusinessObjects.EmployeesCollectionProxyStub server1 = esDataContractSerializer.FromXml(xml, typeof(BusinessObjects.EmployeesCollectionProxyStub))
       as BusinessObjects.EmployeesCollectionProxyStub;

   // Now save the Entity
   server1.GetCollection().Save();
}

member.example:
DynamicQuery allows you to (without writing any stored procedures) query your database on the fly. All selection criteria are passed in via Parameters (SAParameter, OleDbParameter) in order to prevent sql injection techniques often attempted by hackers. Additional examples are provided here:
http://www.entityspaces.net/portal/QueryAPISamples/tabid/80/Default.aspx
EmployeesCollection emps = new EmployeesCollection;
emps.Query.es.CountAll = true; emps.Query.Select ( emps.Query.LastName, emps.Query.FirstName ) .Where ( emps.Query.Or ( emps.Query.LastName.Like("%A%"), emps.Query.LastName.Like("%O%") ), emps.Query.BirthDate.Between("1940-01-01", "2006-12-31") ) .GroupBy ( emps.Query.LastName, emps.Query.FirstName ) .OrderBy ( emps.Query.LastName.Descending, emps.Query.FirstName.Ascending );
emps.Query.Load();

See  Enumeration.

emps.Query.Select
(
	emps.Query.LastName,
	emps.Query.Age.Avg("Average Age")
);

See  Enumeration.

emps.Query.Where
(
	emps.Query.LastName == "Doe" && emps.Query.FirstName.Like("J%")
);

See  Enumeration.

emps.Query.Where
(
	emps.Query.LastName == "Doe" && emps.Query.FirstName.Like("J%")
);

See  Enumeration.

emps.Query.Where
(
	emps.Query.And
	(
		emps.Query.LastName == "Doe",
		emps.Query.FirstName.Like("J%")
	),
	emps.Query.Age.LessThen(50)
);

See  Enumeration.

emps.Query.Where
(
	emps.Query.And
	(
		emps.Query.LastName == "Doe",
		emps.Query.FirstName.Like("J%")
	),
	emps.Query.Age.LessThen(50)
);

See  Enumeration.

emps.Query.Where
(
	emps.Query.Or
	(
		emps.Query.LastName == "Doe",
		emps.Query.FirstName.Like("J%")
	),
	emps.Query.Age.LessThen(50)
);

See  Enumeration.

emps.Query.Where
(
	emps.Query.Or
	(
		emps.Query.LastName == "Doe",
		emps.Query.FirstName.Like("J%")
	),
	emps.Query.Age.LessThen(50)
);

You can order by an aggregate by passing the aggregate alias.
See  Enumeration.

emps.Query.OrderBy
(
	emps.Query.LastName.Descending
);

